import{_ as o,a as s,b as l,c as n,d as p,e as d,f as m,g as c,h,i as u,j as g,k as b,l as f,m as _,n as x,o as v,p as y,q as z,r as i,s as r,t as D,u as e,v as w,w as S,x as P,y as A,z as t,A as G,B as L,C as q,D as C}from"./chunks/DexShare.UQ90JY2f.js";import{_ as k}from"./chunks/DS-M6xx.Dx448PdS.js";import{_ as B}from"./chunks/UImenu.2mWyDoEW.js";import{_ as H}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as N,o as O,c as W,a3 as T}from"./chunks/framework.g9mfNVRQ.js";const K=JSON.parse('{"title":"Sorgente dati","description":"","frontmatter":{"source_hash":"32e9d6dee6","source_commit":"9eea450"},"headers":[],"relativePath":"it/install/datasource.md","filePath":"it/install/datasource.md"}'),E={name:"it/install/datasource.md"};function I(U,a,F,M,V,$){return O(),W("div",null,[...a[0]||(a[0]=[T('<p>Finché non è selezionata una sorgente dati della glicemia, xDrip mostra la procedura guidata della sorgente dati. Puoi attivarla o disattivarla dal <a href="./../use/mainUI.html#blood-drop-menu">menu goccia di sangue</a>, poi con Pulsante Assistente Sorgente.</p><img src="'+o+'" style="zoom:50%;"><p>Scorri verso il basso finché non trovi il tuo sensore o il tuo caso d&#39;uso.</p><h2 id="g6-g7-1-1" tabindex="-1">G6, G7, 1, 1+ <a class="header-anchor" href="#g6-g7-1-1" aria-label="Permalink to &quot;G6, G7, 1, 1+ {#g6-g7-1-1}&quot;">​</a></h2><p>Se colleghi xDrip direttamente al sensore (<a href="./g6.html">G6, G7, 1, 1+</a>), <strong>non potrai</strong> usare l&#39;app del produttore né caricare i dati su Clarity (puoi usare <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> o <a href="./../use/cloud.html#tidepool">Tidepool</a>). Potresti riuscire a condividere i dati tramite i server <a href="./../use/cloud.html#dex-share">Share</a>, ma la condivisione deve essere prima configurata con le app del produttore.</p><img src="'+s+'" style="zoom:50%;"><p>Se usi le app del produttore (G6, G7, 1+), puoi collegare xDrip come <a href="./dexshare.html">Share follower</a>, purché sia stato configurato un follower con le app del produttore.</p><img src="'+l+'" style="zoom:50%;"><p>Se usi <a href="./byod.html">BYODA</a> (solo G6) e hai attivato Broadcast to xDrip, non ti serve una connessione di rete per avere i dati in xDrip. Usa la sorgente dati Inter-app broadcast</p><img src="'+n+'" style="zoom:45%;"><p>Puoi aggiungere xDrip alla tua configurazione attuale e selezionare <a href="./companion.html">Companion App</a> per far leggere a xDrip la glicemia dalle notifiche dell&#39;app del produttore (G6, G7, 1, 1+, Stelo). Nota che con l&#39;app del produttore Stelo fornisce letture ogni 15 minuti.</p><img src="'+p+'" style="zoom:50%;"><p>Ed è possibile anche se usi <a href="./companion.html">CamAPS</a>, sempre con la sorgente dati Companion App</p><img src="'+d+'" style="zoom:50%;"><h2 id="libre" tabindex="-1">Libre <a class="header-anchor" href="#libre" aria-label="Permalink to &quot;Libre {#libre}&quot;">​</a></h2><p>xDrip si collega direttamente ai Libre 2/2+ UE; puoi usare i Libre 1 e i 14 giorni USA con un dispositivo bridge. Gli altri sensori Libre 2 e 3 non sono supportati direttamente.</p><p>Puoi collegare i Libre 2/2+ UE a xDrip aggiungendo <a href="./../use/OOP.html">OOP2</a>. <strong>Non puoi</strong> usare l&#39;app del produttore per gli allarmi (solo per le scansioni NFC) né caricare i dati sui server del produttore (usa <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> o <a href="./../use/cloud.html#tidepool">Tidepool</a>). Usa la sorgente dati <a href="./libreBT.html">Libre Bluetooth</a>.</p><img src="'+m+'" style="zoom:50%;"><p>Poiché i Libre 1 non hanno il Bluetooth, devi aggiungere un dispositivo <a href="./libreBT.html">bridge</a>. Usa la sorgente dati <a href="./libreBT.html">Libre Bluetooth</a>.<br> Alcuni di questi bridge funzionano anche con i Libre 2/2+ UE. Verifica che il tuo sensore non richieda un <a href="./../use/OOP.html">OOP</a>.</p><img src="'+c+'" style="zoom:50%;"><p>Dalla release 2026.11.21 il gruppo Libre include anche la sorgente dati <a href="./li3.html">Li3</a>, che collega xDrip direttamente a un dispositivo Li3 tramite NFC e Bluetooth.</p><p>Per i sensori non supportati (Libre 2/2+ non UE e Libre 3/3+) puoi anche usare Diabox o Juggluco, e poi <a href="./libre2patch.html">trasmettere</a> i dati a xDrip, che li riceverà con la sorgente dati <a href="./libre2patch.html">Libre 2 patched</a> (<strong>non</strong> l&#39;app modificata stessa).</p><img src="'+h+'" style="zoom:50%;"><p>Puoi seguire un CGM Libre 2/2+ o un Libre 3/3+ con xDrip tramite la sorgente dati <a href="./webfollower.html">Web Follower</a>.</p><img src="'+u+'" style="zoom:50%;"><h2 id="guardian-and-minimed" tabindex="-1">Guardian e MiniMed <a class="header-anchor" href="#guardian-and-minimed" aria-label="Permalink to &quot;Guardian e MiniMed {#guardian-and-minimed}&quot;">​</a></h2><p>Con un <a href="./640_670.html">microinfusore 640G/670G</a> devi ricevere i dati glicemici dal microinfusore usando un glucometro collegato al telefono con un cavo OTG.</p><img src="'+k+'" style="zoom:50%;"><p>Puoi aggiungere xDrip alla tua configurazione attuale e selezionare <a href="./companion.html">Companion App</a> per far leggere a xDrip la glicemia dalle notifiche dell&#39;app del produttore.</p><img src="'+g+'" style="zoom:50%;"><p>Puoi seguire i dati del sensore quando sono condivisi tramite <a href="./carelinkfollow.html">Carelink</a>, ma il produttore potrebbe rendere spesso inutilizzabile questa funzione.</p><img src="'+b+'" style="zoom:50%;"><h2 id="aidex" tabindex="-1"><a href="./aidex.html">Aidex</a> <a class="header-anchor" href="#aidex" aria-label="Permalink to &quot;[Aidex](./aidex) {#aidex}&quot;">​</a></h2><p>Puoi ricevere in xDrip i dati dall&#39;app del produttore.</p><p>Puoi aggiungere xDrip alla tua configurazione attuale e selezionare <a href="./companion.html">Companion App</a> per far leggere a xDrip la glicemia dalle notifiche dell&#39;app del produttore.</p><h2 id="sibionics" tabindex="-1">Sibionics <a class="header-anchor" href="#sibionics" aria-label="Permalink to &quot;Sibionics {#sibionics}&quot;">​</a></h2><p>L&#39;<a href="https://t.me/s/kubarev_modz" target="_blank" rel="noreferrer">app modificata</a> ti permette di usare xDrip con la sorgente dati <a href="./640_670.html">Inter-app broadcast</a>.</p><h2 id="caresens-air" tabindex="-1">CareSens Air <a class="header-anchor" href="#caresens-air" aria-label="Permalink to &quot;CareSens Air {#caresens-air}&quot;">​</a></h2><p>Puoi ricevere in xDrip i dati dall&#39;app del produttore con la sorgente dati <a href="./caresens.html">CareSens Air</a> (o Inter-app broadcast).</p><img src="'+f+'" style="zoom:50%;"><br><h2 id="bluetooth-connection-to-a-sensor-or-a-bridge" tabindex="-1">Connessione Bluetooth a un sensore o a un bridge <a class="header-anchor" href="#bluetooth-connection-to-a-sensor-or-a-bridge" aria-label="Permalink to &quot;Connessione Bluetooth a un sensore o a un bridge {#bluetooth-connection-to-a-sensor-or-a-bridge}&quot;">​</a></h2><p>Quando colleghi xDrip direttamente a un sensore, è xDrip a gestire la connessione Bluetooth, o la connessione al dispositivo Bluetooth che invia i dati del tuo sensore (chiamato bridge).</p><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p><strong>NON</strong> provare a collegarti da Impostazioni Android -&gt; Connessioni -&gt; Bluetooth!</p></div><img src="'+_+'" style="zoom:100%;"><p>Se il tuo bridge è associato ad Android, dissocialo prima di continuare.</p><img src="'+x+'" style="zoom:100%;"><div class="warning custom-block"><p class="custom-block-title">Un dispositivo alla volta</p><p>Sensori e bridge possono collegarsi a un solo smartphone (o tablet) alla volta, e a una sola app alla volta.<br> Dovresti disinstallare l&#39;app del produttore per collegare xDrip al tuo sensore o bridge.<br> Se un altro dispositivo è collegato al tuo sensore o bridge, spegnilo o disattiva l&#39;altra app prima di provare a collegarti con xDrip.<br><strong>Non puoi collegarti a due telefoni o app. Con un&#39;eccezione per Dex G6/G7/1 e 1+: il secondo dispositivo può essere solo un ricevitore/microinfusore collegato o un orologio BlueJay.</strong></p></div><br><p>Ora dovresti vedere la procedura guidata di selezione della sorgente dati.</p><img src="'+o+'" style="zoom:50%;"><p>Se non la vedi, tocca questo pulsante per visualizzarla.</p><img src="'+v+'" style="zoom:75%;"><p>Se il pulsante non è visibile, puoi mostrarlo con una pressione prolungata sull&#39;icona di xDrip, attivando <code>Pulsante Assistente Sorgente</code>.</p><img src="'+B+'" style="zoom:75%;"><br><h2 id="sensor-selection" tabindex="-1">Selezione del sensore <a class="header-anchor" href="#sensor-selection" aria-label="Permalink to &quot;Selezione del sensore {#sensor-selection}&quot;">​</a></h2><p>I sensori inutilizzati e obsoleti sono stati rimossi da questa documentazione.</p><h3 id="the-following-sensors-are-supported-directly-by-xdrip" tabindex="-1">I seguenti sensori sono supportati direttamente da xDrip: <a class="header-anchor" href="#the-following-sensors-are-supported-directly-by-xdrip" aria-label="Permalink to &quot;I seguenti sensori sono supportati direttamente da xDrip: {#the-following-sensors-are-supported-directly-by-xdrip}&quot;">​</a></h3><ul><li><a href="./g6.html">G6, G7, 1 e 1+</a><br><img src="'+y+'" style="zoom:54%;"> <img src="'+z+'" style="zoom:50%;"></li><li><a href="./libreBT.html">Libre (con bridge)</a><br><img src="'+i+'" style="zoom:54%;"> <img src="'+r+'" style="zoom:50%;"></li><li>Libre con smartwatch SWR50 modificato<br><img src="'+i+'" style="zoom:54%;"> <img src="'+D+'" style="zoom:51%;"></li><li><a href="./libre2.html">Libre 2 (solo UE)</a><br><img src="'+i+'" style="zoom:54%;"> <img src="'+r+'" style="zoom:50%;"></li><li><a href="./medtrum.html">Medtrum A6</a><br><img src="'+e+'" style="zoom:54%;"> <img src="'+w+'" style="zoom:53%;"></li><li><a href="./caresens.html">CareSens Air</a><br><img src="'+e+'" style="zoom:52%;"> <img src="'+S+'" style="zoom:54%;"></li></ul><h3 id="the-following-sensors-and-features-are-supported-with-a-companion-app" tabindex="-1">I seguenti sensori e funzioni sono supportati con un&#39;app compagno: <a class="header-anchor" href="#the-following-sensors-and-features-are-supported-with-a-companion-app" aria-label="Permalink to &quot;I seguenti sensori e funzioni sono supportati con un&#39;app compagno: {#the-following-sensors-and-features-are-supported-with-a-companion-app}&quot;">​</a></h3><ul><li><a href="./libre2patch.html">Libre 2 (solo UE)</a><br><img src="'+i+'" style="zoom:51%;"> <img src="'+P+'" style="zoom:53%;"></li><li><a href="./eversense.html">Eversense</a><br><img src="'+e+'" style="zoom:52%;"> <img src="'+A+'" style="zoom:53%;"></li><li><a href="./640_670.html">Microinfusori 640G/670G</a><br><img src="'+e+'" style="zoom:52%;"> <img src="'+t+'" style="zoom:53%;"></li><li><a href="./byod.html">Build your own app (BYODA)</a> per sensori G6<br><img src="'+e+'" style="zoom:52%;"> <img src="'+t+'" style="zoom:53%;"></li><li><a href="./aidex.html">Aidex</a><br><img src="'+G+'" style="zoom:53%;"></li><li><a href="./companion.html">Companion App</a> per G6, G7, 1, 1+, CamAPS ed Eversense<br> Vedi più sotto.</li></ul><br><h2 id="follower-mode" tabindex="-1">Modalità follower <a class="header-anchor" href="#follower-mode" aria-label="Permalink to &quot;Modalità follower {#follower-mode}&quot;">​</a></h2><ul><li><a href="./xdripfollower.html">xDrip Sync</a> (richiede i Google Play Services)<br><img src="'+L+'" style="zoom:53%;"></li><li><a href="./nightscoutfollower.html">Nightscout</a><br><img src="'+e+'" style="zoom:52%;"> <img src="'+q+'" style="zoom:53%;"></li><li><a href="./dexshare.html">Dex Share</a><br><img src="'+e+'" style="zoom:52%;"> <img src="'+C+'" style="zoom:53%;"></li><li><a href="./webfollower.html">Libre Web Follower</a><br> Vedi più sotto.</li><li><a href="./carelinkfollow.html">CareLink Follower</a><br> Vedi più sotto.</li></ul><br><h2 id="changing-data-source" tabindex="-1">Cambiare sorgente dati <a class="header-anchor" href="#changing-data-source" aria-label="Permalink to &quot;Cambiare sorgente dati {#changing-data-source}&quot;">​</a></h2><p>Puoi selezionare un&#39;altra sorgente dati senza usare la procedura guidata, dal menu delle impostazioni:</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+H+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dati Hardware di origine</p></div><p><a href="./g6.html">G6, G7, 1 e 1+</a></p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> Dex<span style="float:right;">○ </span>   </p></div><p><a href="./libreBT.html">Libre (con bridge)</a></p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> Libre Bluetooth<span style="float:right;">○ </span>   </p></div><p><a href="https://github.com/tzachi-dar/LibreAllHouse" target="_blank" rel="noreferrer">Libre whole house</a></p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> Libre Bluetooth + wifi<span style="float:right;">○ </span>   <br>  Libre wifi<span style="float:right;">○ </span>   </p></div><p><a href="./xdripfollower.html">xDrip Sync</a></p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> xDrip+ Sync Follower<span style="float:right;">○ </span>   </p></div><p>Libre con smartwatch SWR50 modificato</p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> LibreAlarm<span style="float:right;">○ </span>   </p></div><p><a href="./libre2patch.html">Libre 2 (solo UE), Diabox o Juggluco</a></p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> Libre (patched App)<span style="float:right;">○ </span>   </p></div><p><a href="./640_670.html">Microinfusori 640G/670G</a>, <a href="./eversense.html">Eversense</a> e <a href="./byod.html">Build your own app (BYODA)</a></p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> Inter-app broadcast<span style="float:right;">○ </span>   </p></div><p>Prima della release 2026.09.04 questa sorgente dati si chiamava &quot;640G / EverSense&quot;.</p><p><a href="./medtrum.html">Medtrum A6/S7</a></p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> Medtrum A6<span style="float:right;">○ </span>   </p></div><p><a href="./nightscoutfollower.html">Nightscout</a></p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> Nightscout Follower<span style="float:right;">○ </span>   </p></div><p><a href="./dexshare.html">Dex Share</a></p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> Dex Share Follower<span style="float:right;">○ </span>   </p></div><p><a href="./companion.html">Companion App</a> per G6, G7, One e CamAPS</p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> Companion App<span style="float:right;">○ </span>   </p></div><p><a href="./smartguide.html">SmartGuide</a></p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> SmartGuide<span style="float:right;">○ </span>   </p></div><p><a href="./aidex.html">GlucoRx/Aidex</a></p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> GlucoRx/Aidex App<span style="float:right;">○ </span>   </p></div><p><a href="./webfollower.html">Web Follower</a> per CGM Libre 2 e Libre 3</p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> Web Follower<span style="float:right;">○ </span>   </p></div><p><a href="./carelinkfollow.html">CareLink</a></p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> CareLink Follower<span style="float:right;">○ </span>   </p></div><h5 id="disable-collection" tabindex="-1">Disabilita Collezione <a class="header-anchor" href="#disable-collection" aria-label="Permalink to &quot;Disabilita Collezione {#disable-collection}&quot;">​</a></h5><p>Se vuoi disattivare xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Dati Hardware di origine</p><p> Disabilita Collezione<span style="float:right;">○ </span>   </p></div><br><div class="info custom-block"><p class="custom-block-title">Nota</p><p>L&#39;elenco <code>Dati Hardware di origine</code> contiene anche <code>Bluetooth Wixel</code>, <code>xBridge Wixel</code>, <code>Wifi Wixel</code>, <code>Wifi Wixel + BT Wixel</code> e <code>Wifi Wixel + xBridge Wixel</code>: sono voci legacy/obsolete non trattate in questa documentazione.</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 22/11/2026</em></a></p>',107)])])}const X=N(E,[["render",I]]);export{K as __pageData,X as default};
